"""Replay double of `methods.Learner`: a DQN learner's recorded acts, policy and state.

`act` answers each observation it recorded with its exploring action; `observe` keeps every
transition it is given (in `observed`); `policy()` is a frozen copy acting greedily as recorded.
"""

from typing import Any

import numpy as np

from rllab.core import Array, Policy
from rllab.methods import Transition


class ReplayLearner:
    def __init__(self, kit: Any, recording: dict[str, Any]) -> None:
        replay_policy = kit.module("core.Policy", "double").ReplayPolicy
        self._explore = replay_policy(recording["acts"])
        self._greedy = recording["policy"]
        self._replay_policy = replay_policy
        self._state = dict(recording["state_dict"])
        self.observed: list[Transition] = []

    def act(self, obs: Array, rng: np.random.Generator) -> Array:
        return self._explore.act(obs, rng)

    def observe(self, t: Transition) -> None:
        self.observed.append(t)

    def policy(self) -> Policy:
        frozen: Policy = self._replay_policy(self._greedy)
        return frozen

    def state_dict(self) -> dict[str, object]:
        return dict(self._state)


def build(kit: Any, recording: dict[str, Any]) -> ReplayLearner:
    return ReplayLearner(kit, recording)
"""Replay double of `core.World`: serves one recorded episode.

`reset(seed)` returns the recorded start for any seed (and `result()` reports that seed), so a
training loop can reset it as often as it likes. `step` refuses an action outside `spec.action`
with `ActionError` and a step after `done` with `RuntimeError`, as every World must; any action
inside the action space advances the recording by one step.
"""

from dataclasses import dataclass, field, replace
from typing import Any

import numpy as np

from rllab.core import ActionError, Array, Box, DrawState, EpisodeResult, Step, WorldSpec


def check_actions(spec: WorldSpec, actions: Array, active: Array) -> None:
    """ActionError for the first active agent whose action is outside `spec.action`."""
    for i, row in enumerate(np.asarray(actions)):
        if active[i] and not inside(spec, row):
            raise ActionError(spec.agents[i], row.tolist())


def inside(spec: WorldSpec, action: Array) -> bool:
    if isinstance(spec.action, Box):
        low, high = spec.action.low, spec.action.high
        return action.shape == (spec.action.dims,) and bool(
            np.all((action >= low) & (action <= high))
        )
    return action.shape == () and float(action).is_integer() and 0 <= action < spec.action.n


@dataclass
class ReplayWorld:
    spec: WorldSpec
    steps: list[Step]
    draws: list[DrawState]
    recorded: EpisodeResult
    at: int | None = field(default=None, init=False)
    seed: int = field(default=0, init=False)

    def reset(self, seed: int) -> Step:
        self.at, self.seed = 0, seed
        return self.steps[0]

    def step(self, actions: Array) -> Step:
        if self.at is None or self.steps[self.at].done:
            raise RuntimeError("step before reset or after done")
        check_actions(self.spec, actions, self.steps[self.at].active)
        self.at += 1
        return self.steps[self.at]

    def result(self) -> EpisodeResult:
        return replace(self.recorded, seed=self.seed)

    def draw(self) -> DrawState:
        return self.draws[self.at or 0]


def build(kit: Any, recording: dict[str, Any]) -> ReplayWorld:
    return ReplayWorld(
        kit.decode(WorldSpec, recording["spec"]),
        kit.decode(list[Step], recording["steps"]),
        kit.decode(list[DrawState], recording["draws"]),
        kit.decode(EpisodeResult, recording["result"]),
    )
"""Fake of `train.run_train`: writes the finished 3-checkpoint snake run (runlog.Run sample).

The folder is `<root>/<world>/<variant>/<name>` with `run.json` (the record), `episodes.jsonl`,
`evals.jsonl` (one JSON object per line) and `checkpoints/ckpt_<pct>.pt` (`torch.save` of the
checkpoint's JSON form), as AD-06 lays it out. An existing folder raises `RunExistsError`
before anything is written, as `run_train` must.
"""

import json
from collections.abc import Callable
from dataclasses import replace
from pathlib import Path
from typing import Any

import torch

from rllab.core import RunConfig
from rllab.runlog import RunExistsError, RunRecord


def build(kit: Any) -> Callable[[RunConfig, Path], RunRecord]:
    def run_train(config: RunConfig, root: Path) -> RunRecord:
        folder = root / config.world / config.variant / config.name
        if folder.exists():
            raise RunExistsError(folder)
        recording = kit.read("runlog.Run", "snake_finished")
        record = replace(kit.decode(RunRecord, recording["record"]), config=config, path=folder)
        (folder / "checkpoints").mkdir(parents=True)
        (folder / "run.json").write_text(json.dumps(kit.encode(record), indent=1))
        for log in ("episodes", "evals"):
            lines = [json.dumps(item) + "\n" for item in recording[log]]
            (folder / f"{log}.jsonl").write_text("".join(lines))
        for ckpt in recording["checkpoints"]:
            saved = {**ckpt, "run": config.name}
            torch.save(saved, folder / "checkpoints" / f"ckpt_{ckpt['pct']}.pt")
        return record

    return run_train

